{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values for stage-1 decisions.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage1_perseveration",
      "title": "Stage 1 Perseveration",
      "description": "Adds a bonus to the stage-1 logit of the action chosen in the previous trial.",
      "params": [
        {
          "name": "pers_1",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "if last_action_1 != -1:\n            logits_1[last_action_1] += pers_1",
      "expressible_in_slots": true
    },
    {
      "name": "motor_chunking_bias",
      "title": "Motor Chunking Bias",
      "description": "Adds a bonus to the stage-2 logit corresponding to the same motor action chosen in stage 1 of the current trial.",
      "params": [
        {
          "name": "chunking_bias",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "logits_2[action_1[trial]] += chunking_bias",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the model-free Q-values of all unchosen actions and unvisited states towards zero.",
      "params": [
        {
          "name": "decay",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_1] *= (1 - decay)\n        \n        unchosen_2 = 1 - action_2[trial]\n        q_stage2_mf[state_idx, unchosen_2] *= (1 - decay)\n        \n        unvisited_state = 1 - state_idx\n        q_stage2_mf[unvisited_state, 0] *= (1 - decay)\n        q_stage2_mf[unvisited_state, 1] *= (1 - decay)",
      "expressible_in_slots": true
    }
  ]
}
